import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

const LATE_WINDOW_MS = 2 * 60 * 1000;

/**
 * Auction item, prices in item currency.
 *
 * @trace DSN-015 REQ-001 REQ-002 REQ-004 REQ-009
 */
export class Item {
  constructor(public id: string, public sellerId: string, public title: string, public startingPrice: number, public currency: Currency, public endTime: Date, public status: AuctionStatus, public highestBidAmount: number | null, public highestBidderId: string | null, public winnerId: string | null) {}

  /** Returns true when the item is open and its end time has not passed at `now`. */
  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  /** Returns the smallest amount a new bid must reach: the starting price without bids, otherwise one unit above the highest bid. */
  minimumBid(): number {
    if (this.highestBidAmount === null) {
      return this.startingPrice;
    }
    return this.highestBidAmount + 1;
  }

  /** Moves the end time 2 minutes later when `now` is within the last 2 minutes; throws if the item is not open. */
  extendIfLate(now: Date): boolean {
    if (!this.isOpen(now)) {
      throw new Error(`Item ${this.id} is not open`);
    }
    const remaining = this.endTime.getTime() - now.getTime();
    if (remaining > LATE_WINDOW_MS) {
      return false;
    }
    this.endTime = new Date(this.endTime.getTime() + LATE_WINDOW_MS);
    return true;
  }
}

import { Bid } from './Bid.js';
import { BidService } from './BidService.js';

/**
 * Handles the HTTP route that places a bid on an auction item.
 * @trace DSN-020 REQ-002
 */
export class BidController {
  constructor(private readonly bidService: BidService) {}

  /** Validates the bid input and places it through the bid service; throws Error on invalid input. */
  async placeBid(itemId: string, userId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof userId !== 'string' || userId.length === 0) {
      throw new Error('userId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new Error('amount must be a finite number');
    }
    return this.bidService.placeBid(itemId, userId, amount);
  }
}

import { randomUUID } from 'node:crypto';
import { User } from './User.js';
import { UserStore } from './UserStore.js';

/**
 * Validates display names and issues one user id per name.
 * @trace DSN-021 REQ-008
 */
export class UserService {
  constructor(private readonly userStore: UserStore) {}

  /** Registers a unique display name of 2 to 20 characters and returns the new user; throws if the name is invalid or already taken. */
  async register(displayName: string): Promise<User> {
    if (typeof displayName !== 'string' || displayName.length < 2 || displayName.length > 20) {
      throw new Error('Display name must be 2 to 20 characters');
    }
    const existing = await this.userStore.findByName(displayName);
    if (existing !== null) {
      throw new Error(`Display name ${displayName} is already taken`);
    }
    return this.userStore.save(new User(randomUUID(), displayName));
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  constructor(private readonly itemService: ItemService, public intervalMs: number) {}

  /** Closes every auction whose end time is at or before now; propagates store errors. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { ItemService } from './ItemService.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';
import { Currency } from './Currency.js';

/**
 * HTTP routes for items: POST /items, GET /items, GET /items/:id.
 *
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService, private readonly exchangeRateService: ExchangeRateService) {}

  /** Lists a new open item for a seller; throws Error when a field is missing or invalid. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new Error('userId must be a non-empty string');
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (typeof endTime !== 'string' || endTime.trim() === '') {
      throw new Error('endTime is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!this.isCurrency(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns an item with prices converted to the display currency; throws Error when the id is invalid or the item is not found. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    if (displayCurrency !== undefined && !this.isCurrency(displayCurrency)) {
      throw new Error('displayCurrency must be one of CHF, EUR, USD');
    }
    const item = await this.itemService.getItem(id);
    if (displayCurrency === undefined) {
      return { item, displayCurrency: null, convertedStartingPrice: null, convertedHighestBid: null };
    }
    const target = displayCurrency as Currency;
    const convertedStartingPrice = await this.exchangeRateService.convert(item.startingPrice, item.currency, target);
    const convertedHighestBid =
      item.highestBidAmount === null
        ? null
        : await this.exchangeRateService.convert(item.highestBidAmount, item.currency, target);
    return { item, displayCurrency: target, convertedStartingPrice, convertedHighestBid };
  }

  /** Returns all items currently open for bidding. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  /** Tells whether a value is one of the offered currencies. */
  private isCurrency(value: string): value is Currency {
    return (Object.values(Currency) as string[]).includes(value);
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Creates and reads items, and closes due auctions.
 *
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  /** Lists a new open item for an existing seller; throws on invalid input or unknown seller. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    this.requireText(sellerId, 'sellerId');
    this.requireText(title, 'title');
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!(Object.values(Currency) as string[]).includes(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    const seller = await this.userStore.findById(sellerId);
    if (seller === null) {
      throw new Error(`User ${sellerId} not found`);
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws if the id is invalid or the item is not found. */
  async getItem(id: string): Promise<Item> {
    this.requireText(id, 'id');
    const item = await this.itemStore.findItem(id);
    if (item === null) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items whose auctions are open. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every open auction due at the given time, declares winners or marks items unsold, and publishes each closure. */
  async closeDueAuctions(now: Date): Promise<void> {
    const due = await this.itemStore.findDueItems(now);
    for (const item of due) {
      if (item.status !== AuctionStatus.open) {
        continue;
      }
      if (item.highestBidderId === null) {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      } else {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      }
      const saved = await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(saved);
    }
  }

  private requireText(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';

/**
 * Validates and stores bids, extends end time, and publishes accepted bids to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Accepts a valid bid, extends a late auction, and publishes it; throws on invalid input, unknown item or bidder, or a rejected bid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof bidderId !== 'string' || bidderId.length === 0) {
      throw new Error('bidderId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive number');
    }

    const item = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder = await this.userStore.findById(bidderId);
    if (bidder === null) {
      throw new Error(`User ${bidderId} not found`);
    }

    const now = new Date();
    if (!item.isOpen(now)) {
      throw new Error(`Item ${itemId} is not open for bids`);
    }
    if (item.sellerId === bidderId) {
      throw new Error('The seller cannot bid on their own item');
    }
    const minimum = item.minimumBid();
    if (amount < minimum) {
      throw new Error(`Bid must be at least ${minimum}`);
    }

    const bid = await this.itemStore.saveBid(new Bid(randomUUID(), itemId, bidderId, amount, now));
    item.extendIfLate(now);
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(bid, item);
    return bid;
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an amount between currencies for display; returns null when no rate is available. Throws on an invalid amount or currency. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('amount must be a non-negative finite number');
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`Unsupported currency ${from}`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`Unsupported currency ${to}`);
    }
    if (from === to) {
      return amount;
    }

    const rates = await this.loadRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number') {
      return null;
    }
    return Math.round(amount * rate * 100) / 100;
  }

  /** Returns rates for the base currency from the cache when fresh, otherwise fetches them; returns null when unavailable. */
  private async loadRates(base: Currency): Promise<Record<string, number> | null> {
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: now });
      return rates;
    } catch {
      return null;
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persists users with a unique display name in the API server's SQLite database.
 *
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, displayName TEXT NOT NULL UNIQUE)',
    );
  }

  /** Returns the user with the given display name, or null when none exists. */
  async findByName(displayName: string): Promise<User | null> {
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE displayName = ?')
      .all(displayName) as unknown as { id: string; displayName: string }[];
    if (rows.length === 0) {
      return null;
    }
    return new User(rows[0].id, rows[0].displayName);
  }

  /** Stores a new user with a plain INSERT or updates the row of an already stored user. */
  async save(user: User): Promise<User> {
    const existing = this.db
      .prepare('SELECT id FROM users WHERE id = ?')
      .all(user.id) as unknown as { id: string }[];
    if (existing.length === 0) {
      this.db
        .prepare('INSERT INTO users (id, displayName) VALUES (?, ?)')
        .run(user.id, user.displayName);
    } else {
      this.db
        .prepare('UPDATE users SET displayName = ? WHERE id = ?')
        .run(user.displayName, user.id);
    }
    return user;
  }

  /** Returns the user with the given id, or null when none exists. */
  async findById(id: string): Promise<User | null> {
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE id = ?')
      .all(id) as unknown as { id: string; displayName: string }[];
    if (rows.length === 0) {
      return null;
    }
    return new User(rows[0].id, rows[0].displayName);
  }
}

import { Currency } from '../auction-api/Currency.js';

const API_URL = 'https://api.frankfurter.app';
const CACHE_TTL_MS = 60 * 60 * 1000;
const REQUEST_TIMEOUT_MS = 5000;

/**
 * The only caller of the Frankfurter API, fetching rates over HTTPS and caching them for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<Currency, { rates: Record<string, number>; fetchedAt: number }>();

  constructor() {}

  /** Returns the rates for the base currency, from cache when fresh; throws if the base is unsupported or Frankfurter cannot be reached. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!Object.values(Currency).includes(base)) {
      throw new Error(`Unsupported base currency ${String(base)}`);
    }
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }

    let body: unknown;
    try {
      const response = await fetch(`${API_URL}/latest?from=${base}`, {
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (!response.ok) {
        throw new Error(`Frankfurter responded with status ${response.status}`);
      }
      body = await response.json();
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      throw new Error(`Exchange rates unavailable: ${reason}`);
    }

    const rates = (body as { rates?: Record<string, number> } | null)?.rates;
    if (!rates || typeof rates !== 'object') {
      throw new Error('Exchange rates unavailable: response has no rates');
    }
    this.cache.set(base, { rates: { ...rates }, fetchedAt: Date.now() });
    return { ...rates };
  }
}

import { Item } from './Item.js';
import { EventFeed } from './EventFeed.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state, winner and final bid of an item to the event feed. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (!item || typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item must be an item with a non-empty id');
    }
    const payload = JSON.stringify({
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidderId: item.highestBidderId,
      highestBidAmount: item.highestBidAmount,
    });
    this.eventFeed.publish(`item:${item.id}:closed`, payload);
  }
}

import { Bid } from './Bid.js';
import { EventFeed } from './EventFeed.js';
import { Item } from './Item.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 *
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid to the watchers of its item; throws an Error when the bid does not belong to the item. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (typeof bid.id !== 'string' || bid.id.length === 0) {
      throw new Error('bid id must be a non-empty string');
    }
    if (typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item id must be a non-empty string');
    }
    if (bid.itemId !== item.id) {
      throw new Error(`Bid ${bid.id} does not belong to item ${item.id}`);
    }
    const payload = JSON.stringify({
      id: bid.id,
      itemId: bid.itemId,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

import { WebSocket } from 'ws';

/**
 * Internal ws endpoint that holds the sockets of connected live server instances and fans out published events.
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  constructor(public clients: Set<WebSocket>) {}

  /** Sends the topic and payload to every held open socket and drops closed ones; throws if topic is empty. */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.trim() === '') {
      throw new Error('topic must be a non-empty string');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState !== WebSocket.OPEN) {
        this.clients.delete(socket);
        continue;
      }
      socket.send(message);
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

type ItemRow = {
  id: string;
  sellerId: string;
  title: string;
  startingPrice: number;
  currency: string;
  endTime: number;
  status: string;
  highestBidAmount: number | null;
  highestBidderId: string | null;
  winnerId: string | null;
};

type BidRow = {
  id: string;
  itemId: string;
  bidderId: string;
  amount: number;
  placedAt: number;
};

function toItem(row: ItemRow): Item {
  return new Item(
    row.id,
    row.sellerId,
    row.title,
    row.startingPrice,
    row.currency as Currency,
    new Date(row.endTime),
    row.status as AuctionStatus,
    row.highestBidAmount,
    row.highestBidderId,
    row.winnerId,
  );
}

/**
 * Persistence of items and bids, in the API server's SQLite database.
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  constructor(private readonly db: DatabaseSync) {
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      sellerId TEXT NOT NULL,
      title TEXT NOT NULL,
      startingPrice REAL NOT NULL,
      currency TEXT NOT NULL,
      endTime INTEGER NOT NULL,
      status TEXT NOT NULL,
      highestBidAmount REAL,
      highestBidderId TEXT,
      winnerId TEXT
    )`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      itemId TEXT NOT NULL,
      bidderId TEXT NOT NULL,
      amount REAL NOT NULL,
      placedAt INTEGER NOT NULL
    )`);
  }

  /** Inserts the item, or updates the stored row with the same id. */
  async saveItem(item: Item): Promise<Item> {
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id);
    if (exists) {
      this.db
        .prepare(
          `UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, currency = ?, endTime = ?,
           status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?`,
        )
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.getTime(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    } else {
      this.db
        .prepare(
          `INSERT INTO items (id, sellerId, title, startingPrice, currency, endTime, status,
           highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.getTime(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null when it is not stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db.prepare('SELECT * FROM items WHERE id = ?').get(id);
    return row ? toItem(row as unknown as ItemRow) : null;
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? ORDER BY endTime')
      .all(AuctionStatus.open);
    return (rows as unknown as ItemRow[]).map(toItem);
  }

  /** Returns all items whose end time is at or before the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE endTime <= ? ORDER BY endTime')
      .all(now.getTime());
    return (rows as unknown as ItemRow[]).map(toItem);
  }

  /** Inserts the bid, or updates the stored row with the same id. */
  async saveBid(bid: Bid): Promise<Bid> {
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id);
    if (exists) {
      this.db
        .prepare('UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)')
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime());
    }
    return bid;
  }
}

import WebSocket from 'ws';
import { LiveGateway } from './LiveGateway.js';

/**
 * Client of the API server's internal ws event feed that hands incoming auction events to the live gateway.
 *
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  private socket: WebSocket | null = null;
  private readonly url: string = process.env.API_SERVER_URL ?? 'ws://localhost:8080';
  private readonly path: string = '/internal/live-update-server';

  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the event feed connection and reconnects after a drop; no-op when already open. */
  connect(): void {
    if (this.socket !== null) {
      return;
    }
    const socket = new WebSocket(this.url + this.path);
    this.socket = socket;
    socket.on('message', (data: WebSocket.RawData) => {
      this.handleRaw(data.toString());
    });
    socket.on('close', () => {
      this.socket = null;
      setTimeout(() => this.connect(), 1000);
    });
    socket.on('error', () => {
      socket.close();
    });
  }

  /** Routes one event to the gateway by its item id; throws when the payload has no itemId. */
  onEvent(topic: string, payload: string): void {
    if (topic.trim() === '') {
      throw new Error('topic must be a non-empty string');
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(payload);
    } catch {
      throw new Error('payload must be valid JSON');
    }
    const itemId = (parsed as { itemId?: unknown } | null)?.itemId;
    if (typeof itemId !== 'string' || itemId === '') {
      throw new Error('payload must contain a non-empty itemId');
    }
    this.liveGateway.broadcast(itemId, payload);
  }

  /** Parses one raw feed message of the form {topic, payload} and forwards it; ignores malformed messages. */
  private handleRaw(raw: string): void {
    let message: { topic?: unknown; payload?: unknown };
    try {
      message = JSON.parse(raw);
    } catch {
      return;
    }
    if (typeof message.topic !== 'string' || typeof message.payload !== 'string') {
      return;
    }
    try {
      this.onEvent(message.topic, message.payload);
    } catch {
      return;
    }
  }
}

import type { WebSocket } from 'ws';

/**
 * WebSocket gateway for browsers; holds the open browser sockets by client id and the watchers per item, and sends each broadcast only to the sockets watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private readonly watchers = new Map<string, Set<string>>();

  constructor(public sockets: Map<string, WebSocket>) {}

  /** Registers a client as watching an item; throws when an id is empty. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client's watch on an item; throws when an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) return;
    clients.delete(clientId);
    if (clients.size === 0) this.watchers.delete(itemId);
  }

  /** Sends the message to every open socket watching the item; throws when itemId is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) return;
    for (const clientId of clients) {
      const socket = this.sockets.get(clientId);
      if (socket && socket.readyState === 1) {
        socket.send(message);
      }
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.length === 0) {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}

