{
  "path": "src/live-updates/EventFeedClient.ts",
  "content": "import WebSocket from 'ws';
import { LiveGateway } from './LiveGateway.js';

/**
 * Client of the API server's internal ws event feed that hands incoming auction events to the live gateway.
 *
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  private socket: WebSocket | null = null;
  private readonly url: string = process.env.API_SERVER_URL ?? 'ws://localhost:8080';
  private readonly path: string = '/internal/live-update-server';

  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the event feed connection and reconnects after a drop; no-op when already open. */
  connect(): void {
    if (this.socket !== null) {
      return;
    }
    const socket = new WebSocket(this.url + this.path);
    this.socket = socket;
    socket.on('message', (data: WebSocket.RawData) => {
      this.handleRaw(data.toString());
    });
    socket.on('close', () => {
      this.socket = null;
      setTimeout(() => this.connect(), 1000);
    });
    socket.on('error', () => {
      socket.close();
    });
  }

  /** Routes one event to the gateway by its item id; throws when the payload has no itemId. */
  onEvent(topic: string, payload: string): void {
    if (topic.trim() === '') {
      throw new Error('topic must be a non-empty string');
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(payload);
    } catch {
      throw new Error('payload must be valid JSON');
    }
    const itemId = (parsed as { itemId?: unknown } | null)?.itemId;
    if (typeof itemId !== 'string' || itemId === '') {
      throw new Error('payload must contain a non-empty itemId');
    }
    this.liveGateway.broadcast(itemId, payload);
  }

  /** Parses one raw feed message of the form {topic, payload} and forwards it; ignores malformed messages. */
  private handleRaw(raw: string): void {
    let message: { topic?: unknown; payload?: unknown };
    try {
      message = JSON.parse(raw);
    } catch {
      return;
    }
    if (typeof message.topic !== 'string' || typeof message.payload !== 'string') {
      return;
    }
    try {
      this.onEvent(message.topic, message.payload);
    } catch {
      return;
    }
  }
}
"
}

{
  "path": "src/live-updates/LiveGateway.ts",
  "content": "import type { WebSocket } from 'ws';

/**
 * WebSocket gateway for browsers; holds the open browser sockets by client id and the watchers per item, and sends each broadcast only to the sockets watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private readonly watchers = new Map<string, Set<string>>();

  constructor(public sockets: Map<string, WebSocket>) {}

  /** Registers a client as watching an item; throws when an id is empty. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client's watch on an item; throws when an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) return;
    clients.delete(clientId);
    if (clients.size === 0) this.watchers.delete(itemId);
  }

  /** Sends the message to every open socket watching the item; throws when itemId is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) return;
    for (const clientId of clients) {
      const socket = this.sockets.get(clientId);
      if (socket && socket.readyState === 1) {
        socket.send(message);
      }
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.length === 0) {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}
"
}

{
  "path": "src/auction-api/EventFeed.ts",
  "content": "import { WebSocket } from 'ws';

/**
 * Internal ws endpoint that holds the sockets of connected live server instances and fans out published events.
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  constructor(public clients: Set<WebSocket>) {}

  /** Sends the topic and payload to every held open socket and drops closed ones; throws if topic is empty. */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.trim() === '') {
      throw new Error('topic must be a non-empty string');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState !== WebSocket.OPEN) {
        this.clients.delete(socket);
        continue;
      }
      socket.send(message);
    }
  }
}
"
}

{
  "path": "src/auction-api/ItemController.ts",
  "content": "import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { ItemService } from './ItemService.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';
import { Currency } from './Currency.js';

/**
 * HTTP routes for items: POST /items, GET /items, GET /items/:id.
 *
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService, private readonly exchangeRateService: ExchangeRateService) {}

  /** Lists a new open item for a seller; throws Error when a field is missing or invalid. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new Error('userId must be a non-empty string');
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (typeof endTime !== 'string' || endTime.trim() === '') {
      throw new Error('endTime is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!this.isCurrency(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns an item with prices converted to the display currency; throws Error when the id is invalid or the item is not found. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    if (displayCurrency !== undefined && !this.isCurrency(displayCurrency)) {
      throw new Error('displayCurrency must be one of CHF, EUR, USD');
    }
    const item = await this.itemService.getItem(id);
    if (displayCurrency === undefined) {
      return { item, displayCurrency: null, convertedStartingPrice: null, convertedHighestBid: null };
    }
    const target = displayCurrency as Currency;
    const convertedStartingPrice = await this.exchangeRateService.convert(item.startingPrice, item.currency, target);
    const convertedHighestBid =
      item.highestBidAmount === null
        ? null
        : await this.exchangeRateService.convert(item.highestBidAmount, item.currency, target);
    return { item, displayCurrency: target, convertedStartingPrice, convertedHighestBid };
  }

  /** Returns all items currently open for bidding. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  /** Tells whether a value is one of the offered currencies. */
  private isCurrency(value: string): value is Currency {
    return (Object.values(Currency) as string[]).includes(value);
  }
}
"
}

