import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

type ItemRow = {
  id: string;
  sellerId: string;
  title: string;
  startingPrice: number;
  currency: string;
  endTime: number;
  status: string;
  highestBidAmount: number | null;
  highestBidderId: string | null;
  winnerId: string | null;
};

type BidRow = {
  id: string;
  itemId: string;
  bidderId: string;
  amount: number;
  placedAt: number;
};

function toItem(row: ItemRow): Item {
  return new Item(
    row.id,
    row.sellerId,
    row.title,
    row.startingPrice,
    row.currency as Currency,
    new Date(row.endTime),
    row.status as AuctionStatus,
    row.highestBidAmount,
    row.highestBidderId,
    row.winnerId,
  );
}

/**
 * Persistence of items and bids, in the API server's SQLite database.
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  constructor(private readonly db: DatabaseSync) {
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      sellerId TEXT NOT NULL,
      title TEXT NOT NULL,
      startingPrice REAL NOT NULL,
      currency TEXT NOT NULL,
      endTime INTEGER NOT NULL,
      status TEXT NOT NULL,
      highestBidAmount REAL,
      highestBidderId TEXT,
      winnerId TEXT
    )`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      itemId TEXT NOT NULL,
      bidderId TEXT NOT NULL,
      amount REAL NOT NULL,
      placedAt INTEGER NOT NULL
    )`);
  }

  /** Inserts the item, or updates the stored row with the same id. */
  async saveItem(item: Item): Promise<Item> {
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id);
    if (exists) {
      this.db
        .prepare(
          `UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, currency = ?, endTime = ?,
           status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?`,
        )
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.getTime(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    } else {
      this.db
        .prepare(
          `INSERT INTO items (id, sellerId, title, startingPrice, currency, endTime, status,
           highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.getTime(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null when it is not stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db.prepare('SELECT * FROM items WHERE id = ?').get(id);
    return row ? toItem(row as unknown as ItemRow) : null;
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? ORDER BY endTime')
      .all(AuctionStatus.open);
    return (rows as unknown as ItemRow[]).map(toItem);
  }

  /** Returns all items whose end time is at or before the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE endTime <= ? ORDER BY endTime')
      .all(now.getTime());
    return (rows as unknown as ItemRow[]).map(toItem);
  }

  /** Inserts the bid, or updates the stored row with the same id. */
  async saveBid(bid: Bid): Promise<Bid> {
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id);
    if (exists) {
      this.db
        .prepare('UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)')
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime());
    }
    return bid;
  }
}
"
}

