import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import express from 'express';
import { WebSocketServer, type WebSocket } from 'ws';
import { LiveGateway } from '../live-updates/LiveGateway.js';
import { EventFeedClient } from '../live-updates/EventFeedClient.js';

const sockets = new Map<string, WebSocket>();
const liveGateway = new LiveGateway(sockets);
const eventFeedClient = new EventFeedClient(liveGateway);

const app = express();
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const server = createServer(app);
const wss = new WebSocketServer({ server });
wss.on('connection', (ws) => {
  const clientId = randomUUID();
  const watched = new Set<string>();
  sockets.set(clientId, ws);
  ws.on('message', (data) => {
    try {
      const m = JSON.parse(data.toString()) as { action?: string; itemId?: string };
      if (m.action === 'watch' && typeof m.itemId === 'string') {
        liveGateway.watch(clientId, m.itemId);
        watched.add(m.itemId);
      } else if (m.action === 'unwatch' && typeof m.itemId === 'string') {
        liveGateway.unwatch(clientId, m.itemId);
        watched.delete(m.itemId);
      }
    } catch {
      // ignore malformed messages
    }
  });
  ws.on('close', () => {
    for (const itemId of watched) liveGateway.unwatch(clientId, itemId);
    sockets.delete(clientId);
  });
});

eventFeedClient.connect();

const port = Number(process.env.LIVE_UPDATE_SERVER_PORT ?? 8081);
server.listen(port, () => console.log(`Live update server listening on ${port}`));

